let info = msg.payload;
// Gebruik de middag om timezone-fouten bij het rekenen in Node-RED te vermijden
let d = new Date(info.start + "T12:00:00Z");
let eindD = new Date(info.eind + "T12:00:00Z");
let eliaTaken = [];

while (d <= eindD) {
    let yyyy = d.getUTCFullYear();
    let mm = String(d.getUTCMonth() + 1).padStart(2, '0');
    let dd = String(d.getUTCDate()).padStart(2, '0');
    let dagStr = `${yyyy}-${mm}-${dd}`;

    let nextD = new Date(d.getTime() + 24*3600*1000);
    let n_yyyy = nextD.getUTCFullYear();
    let n_mm = String(nextD.getUTCMonth() + 1).padStart(2, '0');
    let n_dd = String(nextD.getUTCDate()).padStart(2, '0');
    let nextDagStr = `${n_yyyy}-${n_mm}-${n_dd}`;

    eliaTaken.push({
        startLocal: `${dagStr}T00:00:00`,
        eindLocal: `${nextDagStr}T00:00:00`,
        weergave: dagStr
    });
    d = nextD;
}
msg.payload = eliaTaken;
return msg;

let d = msg.payload;
let encodedWhere = encodeURIComponent(`datetime >= "${d.startLocal}" AND datetime < "${d.eindLocal}"`);
// LET OP: timezone=Europe/Brussels toegevoegd! Data wordt perfect lokaal opgehaald.
msg.url = `https://opendata.elia.be/api/explore/v2.1/catalog/datasets/ods046/exports/json?where=${encodedWhere}&timezone=Europe/Brussels`;
msg.dag = d.weergave;
node.status({ fill: "blue", shape: "ring", text: `Vraagt op: ${msg.dag}` });
return msg;

let records = msg.payload; 
if (!Array.isArray(records)) {
    node.status({fill: "red", shape: "ring", text: `${msg.dag}: API Fout!`});
    node.warn(`⚠️ ELIA API FOUT op ${msg.dag}`);
    return null;
}
if (records.length === 0) {
    node.status({fill: "yellow", shape: "ring", text: `${msg.dag}: 0 minuten`});
    return null;
}

let firstRow = records[0];
let priceKey = Object.keys(firstRow).find(k => k.toLowerCase().replace(/_/g, '') === 'positiveimbalanceprice') || 'positive_imbalance_price';
let timeKey = Object.keys(firstRow).find(k => k.toLowerCase().includes('datetime')) || 'datetime';

let parsedRecords = [];
records.forEach(item => {
    let p = parseFloat(item[priceKey]);
    if (!isNaN(p) && item[timeKey]) {
        parsedRecords.push({ timeMs: new Date(item[timeKey]).getTime(), p: p });
    }
});
parsedRecords.sort((a, b) => a.timeMs - b.timeMs);

let points = [];
parsedRecords.forEach(pr => {
    points.push({
        measurement: "onbalans_minuut",
        fields: { prijs: pr.p },
        tags: { type: "onbalans" },
        timestamp: new Date(pr.timeMs)
    });
});

let ontbrekendeMinuten = [];
let expected = 1440;
if (points.length >= 1350 && points.length <= 1390) expected = 1380;
if (points.length >= 1480 && points.length <= 1520) expected = 1500;

if (points.length < expected) {
    let formatT = (ms) => { let d = new Date(ms); return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); };

    for (let i = 1; i < parsedRecords.length; i++) {
        let diff = parsedRecords[i].timeMs - parsedRecords[i-1].timeMs;
        if (diff > 60000) {
            let gatStartMs = parsedRecords[i-1].timeMs + 60000;
            let gatEindMs = parsedRecords[i].timeMs - 60000;
            if (gatStartMs === gatEindMs) ontbrekendeMinuten.push(formatT(gatStartMs));
            else ontbrekendeMinuten.push(`${formatT(gatStartMs)}-${formatT(gatEindMs)}`);
        }
    }
    let tekort = expected - points.length;
    node.status({ fill: "yellow", shape: "dot", text: `${points.length} min (mist ${tekort})` });
    node.warn(`⚠️ ELIA: ${msg.dag} mist ${tekort} min! [${ontbrekendeMinuten.join(' | ')}]`);
} else {
    node.status({ fill: "green", shape: "dot", text: `${msg.dag}: ${points.length} min` });
}

msg.payload = points;
return msg;

