msg.dag = d.weergave;
node.status({ fill: "blue", shape: "ring", text: `Vraagt op: ${msg.dag}` });
return msg;

let records = msg.payload; 
if (!Array.isArray(records) || records.length === 0) {
    node.status({fill: "yellow", shape: "ring", text: `${msg.dag}: Geen data`});
