let info = msg.payload;
msg.url = `https://api.energy-charts.info/v2/price?bzn=BE&start=${info.start}&end=${info.eind}`;
node.status({ fill: "blue", shape: "dot", text: `Vraagt EPEX ${info.jaar} op...` });
return msg;

let dataset = msg.payload.data;

if (!dataset || !Array.isArray(dataset) || dataset.length === 0) {
    node.status({ fill: "red", shape: "ring", text: "EPEX V2 leeg!" });
    return null;
}

let points = [];

dataset.forEach((record, index) => {
    if (record.timestamp && record.values) {
        let rawVal = Object.values(record.values)[0];
        let p = parseFloat(rawVal);

        if (!isNaN(p)) {
            let d = new Date(record.timestamp);
            let nextRecord = dataset[index+1];

            let isUurData = false;
            if (nextRecord && nextRecord.timestamp) {
                // De absolute tijd verschilt altijd exact 3.600.000 ms, ook tijdens de zomertijd overgang!
                let diffMs = new Date(nextRecord.timestamp).getTime() - d.getTime();
                if (diffMs === 3600000) {
                    isUurData = true;
                }
            }
            if (!nextRecord && d.getMinutes() === 0) {
                isUurData = true; 
            }

            points.push({
                measurement: "epex_kwartier",
                fields: { prijs: p },
                tags: { type: "epex" },
                timestamp: d
            });

            if (isUurData) {
                points.push({ measurement: "epex_kwartier", fields: { prijs: p }, tags: { type: "epex" }, timestamp: new Date(d.getTime() + 15*60000) });
                points.push({ measurement: "epex_kwartier", fields: { prijs: p }, tags: { type: "epex" }, timestamp: new Date(d.getTime() + 30*60000) });
                points.push({ measurement: "epex_kwartier", fields: { prijs: p }, tags: { type: "epex" }, timestamp: new Date(d.getTime() + 45*60000) });
            }
        }
    }
});

node.status({ fill: "green", shape: "dot", text: `${points.length} EPEX records gered!` });
msg.payload = points;
return msg;

msg.url = "http://epex_influxdb:8086/api/v2/delete?org=epex_org&bucket=energie_db";
msg.method = "POST";
msg.headers = {
    "Authorization": "Token epex_super_secret_token_2026",
    "Content-Type": "application/json"
};

// Wis alles in de database tussen 2010 en exact 1 januari 2022 00:00:00Z
msg.payload = {
    "start": "2010-01-01T00:00:00Z",
    "stop": "2022-01-01T00:00:00Z"
};

return msg;

// InfluxDB geeft statuscode 204 (No Content) als de delete 100% succesvol is
if (msg.statusCode === 204) {
    node.status({ fill: "green", shape: "dot", text: "Succes! Alles < 2022 is weg." });
    node.warn("✅ SCHONE LEI: Alle data van vóór 2022 is definitief uit InfluxDB verwijderd!");
} else {
    node.status({ fill: "red", shape: "ring", text: `Fout: ${msg.statusCode}` });
    node.warn("❌ Fout bij verwijderen: " + msg.payload);
}
return msg;

// Start van de ods046/ods047 data
let startDatum = new Date("2019-09-30T12:00:00Z");
let eindDatum = new Date();
eindDatum.setUTCHours(12, 0, 0, 0);

let dagen = [];
let d = startDatum;

while (d <= eindDatum) {
    let yyyy = d.getUTCFullYear();
    let mm = String(d.getUTCMonth() + 1).padStart(2, '0');
    let dd = String(d.getUTCDate()).padStart(2, '0');

    // Pak een extreem ruim UTC-venster (-4u tot +28u) om de Belgische dag veilig te omsluiten
    let qStart = new Date(Date.UTC(yyyy, d.getUTCMonth(), d.getUTCDate(), -4, 0, 0));
    let qStop = new Date(Date.UTC(yyyy, d.getUTCMonth(), d.getUTCDate(), 28, 0, 0));

    dagen.push({
        datumSql: `${yyyy}-${mm}-${dd}`,
        startIso: qStart.toISOString(),
        stopIso: qStop.toISOString()
    });

    d = new Date(d.getTime() + 86400000); // +1 dag
}

msg.payload = dagen;
node.status({ fill: "blue", shape: "dot", text: `Genereert ${dagen.length} dagen...` });
return msg;

let info = msg.payload;

msg.query = `
from(bucket: "energie_db")
  |> range(start: ${info.startIso}, stop: ${info.stopIso})
  |> filter(fn: (r) => r["_measurement"] == "epex_kwartier" or r["_measurement"] == "onbalans_kwartier" or r["_measurement"] == "onbalans_minuut")
  |> filter(fn: (r) => r["_field"] == "prijs")
`;

msg.datumSql = info.datumSql;
node.status({ fill: "blue", shape: "ring", text: `Scant: ${info.datumSql}` });

return msg;

if (!msg.payload || !Array.isArray(msg.payload)) return null;

const targetDate = msg.datumSql; // "YYYY-MM-DD"
const dtFormatter = new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Brussels',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false
});

let actualMin = new Set();
let actualQOnb = new Set();
let actualQEpex = new Set();

// 1. Ophalen welke minuten/kwartieren écht in de DB zitten voor deze Lokale Dag
msg.payload.forEach(row => {
    if (!row._time) return;
    let dtStr = dtFormatter.format(new Date(row._time));
    if (dtStr.startsWith(targetDate)) {
        let hhmm = dtStr.substring(11, 16);
        if (row._measurement === "onbalans_minuut") actualMin.add(hhmm);
        else if (row._measurement === "onbalans_kwartier") actualQOnb.add(hhmm);
        else if (row._measurement === "epex_kwartier") actualQEpex.add(hhmm);
    }
});

// 2. Simuleer hoeveel minuten deze specifieke dag hoort te hebben (houdt perfect rekening met zomertijd!)
let expectedMin = [];
let expectedQ = [];
let baseMs = new Date(targetDate + "T12:00:00Z").getTime() - 24 * 3600 * 1000;
for(let i = 0; i < 48 * 60; i++) {
    let d = new Date(baseMs + i * 60000);
    let dtStr = dtFormatter.format(d);
    if (dtStr.startsWith(targetDate)) {
        let hhmm = dtStr.substring(11, 16);
        expectedMin.push({ ms: d.getTime(), hhmm: hhmm });
        if (d.getMinutes() % 15 === 0) expectedQ.push(hhmm);
    }
}

// 3. Vergelijk verwacht met werkelijk
let missingMinRapport = [];
let missingMinMs = [];
expectedMin.forEach(item => {
    if (!actualMin.has(item.hhmm)) {
        missingMinRapport.push(item.hhmm);
        missingMinMs.push(item.ms);
    }
});

let missingQOnbRapport = expectedQ.filter(q => !actualQOnb.has(q));
let missingQEpexRapport = expectedQ.filter(q => !actualQEpex.has(q));

// 4. Maak leesbare tekst voor de minuten ("02:00-02:59")
function formatGaten(tijdenMs) {
    if (tijdenMs.length === 0) return "";
    let gaten = [];
    let formatT = (ms) => dtFormatter.format(new Date(ms)).substring(11, 16);

    let startGat = tijdenMs[0];
    for (let i = 1; i <= tijdenMs.length; i++) {
        if (i === tijdenMs.length || tijdenMs[i] !== tijdenMs[i - 1] + 60000) {
            let eindGat = tijdenMs[i - 1];
            if (startGat === eindGat) gaten.push(formatT(startGat));
            else gaten.push(`${formatT(startGat)}-${formatT(eindGat)}`);
            if (i < tijdenMs.length) startGat = tijdenMs[i];
        }
    }
    return gaten.join(' | ');
}

let minGatenTekst = formatGaten(missingMinMs);

// 5. Bouw SQL Arrays (Alleen wegschrijven als er effectief iets mist!)
let sqlQuery = `INSERT INTO data_gaten (datum, api_type, aantal_gemist, gaten_details) VALUES (?, ?, ?, ?) ON DUPLICATE KEY UPDATE aantal_gemist = VALUES(aantal_gemist), gaten_details = VALUES(gaten_details)`;

let dbMsgs = [];

if (missingMinRapport.length > 0) {
    dbMsgs.push({ topic: sqlQuery, payload: [targetDate, 'elia_minuut', missingMinRapport.length, minGatenTekst] });
}
if (missingQOnbRapport.length > 0) {
    dbMsgs.push({ topic: sqlQuery, payload: [targetDate, 'elia_kwartier', missingQOnbRapport.length, missingQOnbRapport.join(', ')] });
}
if (missingQEpexRapport.length > 0) {
    dbMsgs.push({ topic: sqlQuery, payload: [targetDate, 'epex_kwartier', missingQEpexRapport.length, missingQEpexRapport.join(', ')] });
}

if (dbMsgs.length > 0) {
    node.status({ fill: "yellow", shape: "dot", text: `${targetDate}: Gat gevonden!` });
    return [dbMsgs]; // Stuurt elke SQL-taak rechtstreeks naar MariaDB zonder Split-node
} else {
    node.status({ fill: "green", shape: "dot", text: `${targetDate}: 100% Compleet` });
    return null; // Niets naar MariaDB sturen
}

msg.payload = dbMsgs;
return msg;
